-- Table: appointment
DROP TABLE IF EXISTS `appointment`;
CREATE TABLE `appointment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `therapist_id` int NOT NULL,
  `patient_id` int NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `location` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `notes` text COLLATE utf8mb4_bin,
  `therapy_type` varchar(120) COLLATE utf8mb4_bin DEFAULT NULL,
  `duration_minutes` int DEFAULT NULL,
  `games` text COLLATE utf8mb4_bin,
  `attendance` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `status_changed_at` datetime DEFAULT NULL,
  `status_changed_by` int DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
