-- Table: appointment_game
DROP TABLE IF EXISTS `appointment_game`;
CREATE TABLE `appointment_game` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `game_id` int NOT NULL,
  `config` text COLLATE utf8mb4_bin,
  `status` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `game_id` (`game_id`),
  KEY `fk_appointment_game_created_by_id_user` (`created_by_id`),
  CONSTRAINT `appointment_game_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `appointment_game_ibfk_2` FOREIGN KEY (`game_id`) REFERENCES `game` (`id`),
  CONSTRAINT `fk_appointment_game_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30016 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

