-- Table: audit_report
DROP TABLE IF EXISTS `audit_report`;
CREATE TABLE `audit_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `transcription_id` int NOT NULL,
  `compliance_index` float NOT NULL,
  `objectives_analysis` longtext COLLATE utf8mb4_bin,
  `summary` text COLLATE utf8mb4_bin,
  `generated_at` datetime DEFAULT NULL,
  `generated_by` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `transcription_id` (`transcription_id`),
  CONSTRAINT `audit_report_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `audit_report_ibfk_2` FOREIGN KEY (`transcription_id`) REFERENCES `transcription` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

