-- Table: contract
DROP TABLE IF EXISTS `contract`;
CREATE TABLE `contract` (
  `id` int NOT NULL AUTO_INCREMENT,
  `is_active` tinyint(1) DEFAULT NULL,
  `patient_id` int NOT NULL,
  `name` varchar(200) DEFAULT NULL,
  `total_amount` float NOT NULL,
