-- Table: daily_report
DROP TABLE IF EXISTS `daily_report`;
CREATE TABLE `daily_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `therapist_id` int NOT NULL,
  `date` date NOT NULL,
  `sessions_count` int DEFAULT NULL,
  `avg_score` float DEFAULT NULL,
  `notes` text COLLATE utf8mb4_bin,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_daily_report` (`patient_id`,`therapist_id`,`date`),
  KEY `therapist_id` (`therapist_id`),
  KEY `fk_daily_report_created_by_id_user` (`created_by_id`),
  KEY `idx_daily_report_patient` (`patient_id`),
  CONSTRAINT `daily_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `daily_report_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_daily_report_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

