  PRIMARY KEY (`id`),
  UNIQUE KEY `filename` (`filename`),
  KEY `fk_game_created_by_id_user` (`created_by_id`),
  KEY `idx_game_is_active` (`is_active`),
  CONSTRAINT `fk_game_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

