-- Table: incidente
DROP TABLE IF EXISTS `incidente`;
CREATE TABLE `incidente` (
  `id_incidente` int NOT NULL AUTO_INCREMENT,
  `titulo` varchar(200) NOT NULL,
  `descripcion` text NOT NULL,
  `appointment_id` int DEFAULT NULL,
  `user_id` int NOT NULL,
  `reports_to_id` int DEFAULT NULL,
  `categoria` varchar(50) NOT NULL,
  `subcategoria` varchar(100) DEFAULT NULL,
  `prioridad` int NOT NULL,
  `estado` varchar(50) NOT NULL,
  `responsable_id` int DEFAULT NULL,
  `evidencia_original` text NOT NULL,
  `evidencia_tipo` varchar(50) NOT NULL,
  `evidencia_metadata` text,
  `fecha_creacion` datetime NOT NULL,
  `fecha_limite_sla` datetime DEFAULT NULL,
  `fecha_resolucion` datetime DEFAULT NULL,
  `escalamiento_nivel` int DEFAULT NULL,
  `horas_invertidas` float DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL,
  `impacto` int NOT NULL DEFAULT '2',
  `urgencia` int NOT NULL DEFAULT '2',
  `post_mortem` text,
  `causa_raiz` text,
  `lecciones_aprendidas` text,
  PRIMARY KEY (`id_incidente`),
  KEY `created_by_id` (`created_by_id`),
  KEY `ix_incidente_reports_to_id` (`reports_to_id`),
  KEY `ix_incidente_prioridad` (`prioridad`),
  KEY `ix_incidente_responsable_id` (`responsable_id`),
  KEY `ix_incidente_user_id` (`user_id`),
  KEY `ix_incidente_estado` (`estado`),
  KEY `ix_incidente_fecha_limite_sla` (`fecha_limite_sla`),
  KEY `ix_incidente_categoria` (`categoria`),
  KEY `ix_incidente_appointment_id` (`appointment_id`),
  CONSTRAINT `incidente_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `incidente_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),
  CONSTRAINT `incidente_ibfk_3` FOREIGN KEY (`reports_to_id`) REFERENCES `user` (`id`),
  CONSTRAINT `incidente_ibfk_4` FOREIGN KEY (`responsable_id`) REFERENCES `user` (`id`),
  CONSTRAINT `incidente_ibfk_5` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

