-- Table: incidente_comentario
DROP TABLE IF EXISTS `incidente_comentario`;
CREATE TABLE `incidente_comentario` (
  `id_comentario` int NOT NULL AUTO_INCREMENT,
  `incidente_id` int NOT NULL,
  `autor_id` int NOT NULL,
  `contenido` text NOT NULL,
  `es_interno` tinyint(1) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id_comentario`),
  KEY `autor_id` (`autor_id`),
  KEY `ix_incidente_comentario_incidente_id` (`incidente_id`),
  CONSTRAINT `incidente_comentario_ibfk_1` FOREIGN KEY (`incidente_id`) REFERENCES `incidente` (`id_incidente`) ON DELETE CASCADE,
  CONSTRAINT `incidente_comentario_ibfk_2` FOREIGN KEY (`autor_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: incidente_historial
DROP TABLE IF EXISTS `incidente_historial`;
CREATE TABLE `incidente_historial` (
  `id_historial` int NOT NULL AUTO_INCREMENT,
  `incidente_id` int NOT NULL,
  `estado_anterior` varchar(50) DEFAULT NULL,
  `estado_nuevo` varchar(50) NOT NULL,
  `comentario` text,
  `changed_by_id` int NOT NULL,
  `changed_at` datetime NOT NULL,
  `escalamiento_nivel` int DEFAULT NULL,
  `responsable_anterior_id` int DEFAULT NULL,
  `responsable_nuevo_id` int DEFAULT NULL,
  PRIMARY KEY (`id_historial`),
  KEY `changed_by_id` (`changed_by_id`),
  KEY `ix_incidente_historial_incidente_id` (`incidente_id`),
  KEY `ix_incidente_historial_changed_at` (`changed_at`),
  CONSTRAINT `incidente_historial_ibfk_1` FOREIGN KEY (`incidente_id`) REFERENCES `incidente` (`id_incidente`) ON DELETE CASCADE,
  CONSTRAINT `incidente_historial_ibfk_2` FOREIGN KEY (`changed_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `incidente_historial` (`id_historial`, `incidente_id`, `estado_anterior`, `estado_nuevo`, `comentario`, `changed_by_id`, `changed_at`, `escalamiento_nivel`, `responsable_anterior_id`, `responsable_nuevo_id`) VALUES
