-- Table: installment
DROP TABLE IF EXISTS `installment`;
CREATE TABLE `installment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `is_active` tinyint(1) DEFAULT NULL,
  `contract_id` int NOT NULL,
  `number` int NOT NULL,
  `due_date` date NOT NULL,
  `amount` float NOT NULL,
  `paid_amount` float DEFAULT NULL,
  `paid_date` datetime DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `payment_id` int DEFAULT NULL,
  `reminder_sent` tinyint(1) DEFAULT NULL,
  `notes` text,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `payment_id` (`payment_id`),
  KEY `ix_installment_due_date` (`due_date`),
  KEY `ix_installment_status` (`status`),
  KEY `ix_installment_contract_id` (`contract_id`),
  KEY `ix_installment_created_by_id` (`created_by_id`),
  CONSTRAINT `installment_ibfk_1` FOREIGN KEY (`contract_id`) REFERENCES `contract` (`id`),
  CONSTRAINT `installment_ibfk_2` FOREIGN KEY (`payment_id`) REFERENCES `payment` (`id`),
  CONSTRAINT `installment_ibfk_3` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: message
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sender_id` int NOT NULL,
  `receiver_id` int NOT NULL,
  `subject` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `body` text COLLATE utf8mb4_bin NOT NULL,
  `is_read` tinyint(1) NOT NULL,
  `created_at` datetime NOT NULL,
  `parent_message_id` int DEFAULT NULL,
  `attachment_path` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL,
  `attachment_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `chat_id` int DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_bin DEFAULT 'sent',
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sender_id` (`sender_id`),
  KEY `receiver_id` (`receiver_id`),
  KEY `parent_message_id` (`parent_message_id`),
  KEY `fk_message_created_by_id_user` (`created_by_id`),
  KEY `idx_message_sender` (`sender_id`),
  KEY `idx_message_receiver` (`receiver_id`),
  KEY `idx_message_chat` (`chat_id`),
  KEY `idx_message_status` (`status`),
  CONSTRAINT `fk_message_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `message_ibfk_1` FOREIGN KEY (`sender_id`) REFERENCES `user` (`id`),
  CONSTRAINT `message_ibfk_2` FOREIGN KEY (`receiver_id`) REFERENCES `user` (`id`),
  CONSTRAINT `message_ibfk_3` FOREIGN KEY (`parent_message_id`) REFERENCES `message` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30053 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

