-- Table: monthly_report
DROP TABLE IF EXISTS `monthly_report`;
CREATE TABLE `monthly_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `therapist_id` int NOT NULL,
  `month` int NOT NULL,
  `year` int NOT NULL,
  `sessions_count` int DEFAULT NULL,
  `avg_score` float DEFAULT NULL,
  `objectives_achieved` int DEFAULT NULL,
  `objectives_total` int DEFAULT NULL,
  `report_text` text COLLATE utf8mb4_bin,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_monthly_report` (`patient_id`,`therapist_id`,`month`,`year`),
  KEY `therapist_id` (`therapist_id`),
  KEY `fk_monthly_report_created_by_id_user` (`created_by_id`),
  KEY `idx_monthly_report_patient` (`patient_id`),
  CONSTRAINT `fk_monthly_report_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `monthly_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `monthly_report_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Table: notification
DROP TABLE IF EXISTS `notification`;
CREATE TABLE `notification` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `message` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `is_read` tinyint(1) NOT NULL,
  `timestamp` datetime NOT NULL,
  `link` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `type` varchar(50) COLLATE utf8mb4_bin DEFAULT 'info',
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `category` varchar(50) COLLATE utf8mb4_bin NOT NULL DEFAULT 'system',
  `priority` varchar(20) COLLATE utf8mb4_bin NOT NULL DEFAULT 'normal',
  `icon` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `metadata_json` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `fk_notification_created_by_id_user` (`created_by_id`),
  KEY `idx_notification_user` (`user_id`),
  KEY `idx_notification_is_read` (`is_read`),
  CONSTRAINT `fk_notification_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `notification_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

