-- Table: patient_group
DROP TABLE IF EXISTS `patient_group`;
CREATE TABLE `patient_group` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `sede_id` int DEFAULT NULL,
  `start_time` varchar(5) DEFAULT NULL,
  `end_time` varchar(5) DEFAULT NULL,
  `work_days` varchar(20) DEFAULT NULL,
  `notes` text,
  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sede_id` (`sede_id`),
  KEY `ix_patient_group_created_by_id` (`created_by_id`),
  CONSTRAINT `patient_group_ibfk_1` FOREIGN KEY (`sede_id`) REFERENCES `sede` (`id`),
  CONSTRAINT `patient_group_ibfk_2` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: patient_group_member
DROP TABLE IF EXISTS `patient_group_member`;
CREATE TABLE `patient_group_member` (
  `group_id` int NOT NULL,
  `patient_id` int NOT NULL,
  PRIMARY KEY (`group_id`,`patient_id`),
  KEY `patient_id` (`patient_id`),
  CONSTRAINT `patient_group_member_ibfk_1` FOREIGN KEY (`group_id`) REFERENCES `patient_group` (`id`),
  CONSTRAINT `patient_group_member_ibfk_2` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: patient_therapist
DROP TABLE IF EXISTS `patient_therapist`;
CREATE TABLE `patient_therapist` (
  `patient_id` int NOT NULL,
  `therapist_id` int NOT NULL,
  PRIMARY KEY (`patient_id`,`therapist_id`),
  KEY `therapist_id` (`therapist_id`),
  CONSTRAINT `patient_therapist_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `patient_therapist_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

