-- Table: payment
DROP TABLE IF EXISTS `payment`;
CREATE TABLE `payment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `amount` float NOT NULL,
  `date` datetime NOT NULL,
  `method` varchar(50) COLLATE utf8mb4_bin NOT NULL,
  `reference` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `receipt_image_path` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `notes` text COLLATE utf8mb4_bin,
  `discount` float DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `installment_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_id` (`patient_id`),
  KEY `fk_payment_created_by_id_user` (`created_by_id`),
  KEY `idx_payment_patient` (`patient_id`),
  KEY `idx_payment_status` (`status`),
  KEY `ix_payment_patient_status` (`patient_id`,`status`),
  KEY `idx_payment_installment` (`installment_id`),
  CONSTRAINT `fk_payment_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `payment_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30064 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

