-- Table: progress_report
DROP TABLE IF EXISTS `progress_report`;
CREATE TABLE `progress_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `block_start_date` date NOT NULL,
  `block_end_date` date NOT NULL,
  `summary` text COLLATE utf8mb4_bin,
  `objectives_progress` longtext COLLATE utf8mb4_bin,
  `status` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  `approved_by_id` int DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_id` (`patient_id`),
  KEY `approved_by_id` (`approved_by_id`),
  CONSTRAINT `progress_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `progress_report_ibfk_2` FOREIGN KEY (`approved_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Table: quarterly_report
DROP TABLE IF EXISTS `quarterly_report`;
CREATE TABLE `quarterly_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `therapist_id` int NOT NULL,
  `quarter` int NOT NULL,
  `year` int NOT NULL,
  `sessions_count` int DEFAULT NULL,
  `avg_score` float DEFAULT NULL,
  `objectives_achieved` int DEFAULT NULL,
  `objectives_total` int DEFAULT NULL,
  `report_text` text COLLATE utf8mb4_bin,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_quarterly_report` (`patient_id`,`therapist_id`,`quarter`,`year`),
  KEY `therapist_id` (`therapist_id`),
  KEY `fk_quarterly_report_created_by_id_user` (`created_by_id`),
  KEY `idx_quarterly_report_patient` (`patient_id`),
  CONSTRAINT `fk_quarterly_report_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `quarterly_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `quarterly_report_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

