-- Table: service_request
DROP TABLE IF EXISTS `service_request`;
CREATE TABLE `service_request` (
  `id` int NOT NULL AUTO_INCREMENT,
  `is_active` tinyint(1) DEFAULT NULL,
  `requester_id` int NOT NULL,
  `category` varchar(50) NOT NULL,
  `title` varchar(200) NOT NULL,
  `description` text,
  `status` varchar(20) DEFAULT NULL,
  `priority` varchar(20) DEFAULT NULL,
  `approved_by_id` int DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `admin_notes` text,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_service_request_category` (`category`),
  KEY `ix_service_request_status` (`status`),
  KEY `ix_service_request_requester_id` (`requester_id`),
  KEY `ix_service_request_created_by_id` (`created_by_id`),
  KEY `ix_service_request_approved_by_id` (`approved_by_id`),
  CONSTRAINT `service_request_ibfk_1` FOREIGN KEY (`requester_id`) REFERENCES `user` (`id`),
  CONSTRAINT `service_request_ibfk_2` FOREIGN KEY (`approved_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `service_request_ibfk_3` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: session_audit
DROP TABLE IF EXISTS `session_audit`;
CREATE TABLE `session_audit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `planned_text` text COLLATE utf8mb4_bin,
  `docx_uploaded_at` datetime DEFAULT NULL,
  `docx_uploaded_by` int DEFAULT NULL,
  `transcript_text` text COLLATE utf8mb4_bin,
  `audio_transcribed_at` datetime DEFAULT NULL,
  `audio_duration_seconds` int DEFAULT NULL,
  `audit_report_json` text COLLATE utf8mb4_bin,
  `audit_score` float DEFAULT NULL,
  `audit_status` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  `audited_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `feedback_engagement` int DEFAULT NULL,
  `feedback_progress` int DEFAULT NULL,
  `feedback_notes` text COLLATE utf8mb4_bin,
  `feedback_submitted_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `appointment_id` (`appointment_id`),
  KEY `docx_uploaded_by` (`docx_uploaded_by`),
  KEY `fk_session_audit_created_by_id_user` (`created_by_id`),
  KEY `idx_session_audit_appointment` (`appointment_id`),
  KEY `idx_session_audit_status` (`audit_status`),
  CONSTRAINT `fk_session_audit_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `session_audit_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `session_audit_ibfk_2` FOREIGN KEY (`docx_uploaded_by`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30069 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

INSERT INTO `session_audit` (`id`, `appointment_id`, `planned_text`, `docx_uploaded_at`, `docx_uploaded_by`, `transcript_text`, `audio_transcribed_at`, `audio_duration_seconds`, `audit_report_json`, `audit_score`, `audit_status`, `audited_at`, `created_at`, `updated_at`, `feedback_engagement`, `feedback_progress`, `feedback_notes`, `feedback_submitted_at`, `created_by_id`, `is_active`) VALUES
