-- Table: session_image
DROP TABLE IF EXISTS `session_image`;
CREATE TABLE `session_image` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `image_path` varchar(500) COLLATE utf8mb4_bin NOT NULL,
  `image_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `uploaded_at` datetime DEFAULT NULL,
  `uploaded_by_id` int NOT NULL,
  `notes` text COLLATE utf8mb4_bin,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `uploaded_by_id` (`uploaded_by_id`),
  KEY `fk_session_image_created_by_id_user` (`created_by_id`),
  KEY `idx_session_image_appointment` (`appointment_id`),
  CONSTRAINT `fk_session_image_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `session_image_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `session_image_ibfk_2` FOREIGN KEY (`uploaded_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30011 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

