  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `session_id` (`session_id`),
  KEY `game_id` (`game_id`),
  KEY `fk_session_metrics_created_by_id_user` (`created_by_id`),
  KEY `idx_session_metrics_user` (`user_id`),
  KEY `idx_session_metrics_session` (`session_id`),
  CONSTRAINT `fk_session_metrics_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `session_metrics_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),
  CONSTRAINT `session_metrics_ibfk_2` FOREIGN KEY (`session_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `session_metrics_ibfk_3` FOREIGN KEY (`game_id`) REFERENCES `game` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30012 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

