-- Table: session_recording
DROP TABLE IF EXISTS `session_recording`;
CREATE TABLE `session_recording` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `file_path` varchar(500) COLLATE utf8mb4_bin NOT NULL,
  `file_size` bigint DEFAULT NULL,
  `duration_seconds` float DEFAULT NULL,
  `mime_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `status` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  `uploaded_by_id` int NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `uploaded_by_id` (`uploaded_by_id`),
  CONSTRAINT `session_recording_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `session_recording_ibfk_2` FOREIGN KEY (`uploaded_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Table: smart_action
DROP TABLE IF EXISTS `smart_action`;
CREATE TABLE `smart_action` (
  `id` int NOT NULL AUTO_INCREMENT,
