  `status` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_smart_action_module` (`module`),
  KEY `ix_smart_action_status` (`status`),
  KEY `fk_smart_action_created_by_id_user` (`created_by_id`),
  KEY `idx_smart_action_status` (`status`),
  KEY `idx_smart_action_module` (`module`),
  CONSTRAINT `fk_smart_action_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30146 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

