-- Table: therapist_sede
DROP TABLE IF EXISTS `therapist_sede`;
CREATE TABLE `therapist_sede` (
  `therapist_id` int NOT NULL,
  `sede_id` int NOT NULL,
  PRIMARY KEY (`therapist_id`,`sede_id`),
  KEY `sede_id` (`sede_id`),
  CONSTRAINT `therapist_sede_ibfk_1` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`),
  CONSTRAINT `therapist_sede_ibfk_2` FOREIGN KEY (`sede_id`) REFERENCES `sede` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

INSERT INTO `therapist_sede` (`therapist_id`, `sede_id`) VALUES
