-- Table: therapy_objective
DROP TABLE IF EXISTS `therapy_objective`;
CREATE TABLE `therapy_objective` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `description` text COLLATE utf8mb4_bin NOT NULL,
  `status` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  `source` varchar(30) COLLATE utf8mb4_bin DEFAULT NULL,
  `sort_order` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  CONSTRAINT `therapy_objective_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Table: transcription
DROP TABLE IF EXISTS `transcription`;
CREATE TABLE `transcription` (
  `id` int NOT NULL AUTO_INCREMENT,
  `appointment_id` int NOT NULL,
  `recording_id` int NOT NULL,
  `full_text` text COLLATE utf8mb4_bin NOT NULL,
  `segments` longtext COLLATE utf8mb4_bin,
  `model_used` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `language` varchar(10) COLLATE utf8mb4_bin DEFAULT NULL,
  `confidence_score` float DEFAULT NULL,
  `processing_time_ms` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `recording_id` (`recording_id`),
  CONSTRAINT `transcription_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `transcription_ibfk_2` FOREIGN KEY (`recording_id`) REFERENCES `session_recording` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Table: user
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_bin NOT NULL,
  `password` varchar(1200) COLLATE utf8mb4_bin NOT NULL,
  `role` varchar(50) COLLATE utf8mb4_bin NOT NULL,
  `oauth_provider` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `oauth_id` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `avatar` varchar(400) COLLATE utf8mb4_bin DEFAULT NULL,
  `phone` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `guardian_name` varchar(150) COLLATE utf8mb4_bin DEFAULT NULL,
  `guardian_contact` varchar(150) COLLATE utf8mb4_bin DEFAULT NULL,
  `therapy_goals` text COLLATE utf8mb4_bin,
  `timezone` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `notes` text COLLATE utf8mb4_bin,
  `assigned_therapist_id` int DEFAULT NULL,
  `game_profile` text COLLATE utf8mb4_bin,
  `admin_password_changed_count` int DEFAULT NULL,
  `payment_plan` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `payment_due_date` date DEFAULT NULL,
  `payment_amount` float DEFAULT NULL,
  `sessions_total` int DEFAULT NULL,
  `sessions_attended` int DEFAULT NULL,
  `session_cost` float DEFAULT NULL,
  `plan_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `has_second_shift` tinyint(1) DEFAULT NULL,
  `modality_2` int DEFAULT NULL,
  `payment_amount_2` float DEFAULT NULL,
  `sessions_total_2` int DEFAULT NULL,
  `sessions_attended_2` int DEFAULT NULL,
  `session_cost_2` float DEFAULT NULL,
  `plan_type_2` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `salary_base` float DEFAULT NULL,
  `contract_hours` int DEFAULT NULL,
  `work_start_time` varchar(5) COLLATE utf8mb4_bin DEFAULT NULL,
  `work_end_time` varchar(5) COLLATE utf8mb4_bin DEFAULT NULL,
  `work_days` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `branch_id` int DEFAULT NULL,
  `sede_id` int DEFAULT NULL,
  `max_patients` int DEFAULT '20',
  `payment_day` int DEFAULT NULL,
  `sessions_remaining` int DEFAULT '0',
  `account_status` varchar(50) COLLATE utf8mb4_bin DEFAULT 'active',
  `document_number` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `mfa_enabled` tinyint(1) DEFAULT '0',
  `otp_secret` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL,
  `mfa_failed_attempts` int DEFAULT '0',
  `mfa_locked_until` datetime DEFAULT NULL,
  `guardian_dni` varchar(15) COLLATE utf8mb4_bin DEFAULT NULL,
  `sex` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `preliminary_diagnosis` text COLLATE utf8mb4_bin,
  `guardian_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `assigned_therapist_id` (`assigned_therapist_id`),
  KEY `fk_user_branch` (`branch_id`),
  KEY `fk_user_sede` (`sede_id`),
  KEY `fk_user_created_by_id_user` (`created_by_id`),
  KEY `idx_user_email` (`email`),
  KEY `idx_user_role` (`role`),
  KEY `idx_user_is_active` (`is_active`),
  KEY `idx_user_guardian_dni` (`guardian_dni`),
  CONSTRAINT `fk_user_branch` FOREIGN KEY (`branch_id`) REFERENCES `branch` (`id`),
  CONSTRAINT `fk_user_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_user_sede` FOREIGN KEY (`sede_id`) REFERENCES `sede` (`id`),
  CONSTRAINT `user_ibfk_1` FOREIGN KEY (`assigned_therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30075 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

