-- Table: user_notification_preference
DROP TABLE IF EXISTS `user_notification_preference`;
CREATE TABLE `user_notification_preference` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `debt_enabled` tinyint(1) DEFAULT NULL,
  `activity_enabled` tinyint(1) DEFAULT NULL,
  `system_enabled` tinyint(1) DEFAULT NULL,
  `alert_enabled` tinyint(1) DEFAULT NULL,
  `payment_enabled` tinyint(1) DEFAULT NULL,
  `sound_enabled` tinyint(1) DEFAULT NULL,
  `browser_notifications` tinyint(1) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `ix_user_notification_preference_created_by_id` (`created_by_id`),
  CONSTRAINT `user_notification_preference_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),
  CONSTRAINT `user_notification_preference_ibfk_2` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `user_notification_preference` (`id`, `user_id`, `debt_enabled`, `activity_enabled`, `system_enabled`, `alert_enabled`, `payment_enabled`, `sound_enabled`, `browser_notifications`, `created_at`, `created_by_id`, `updated_at`) VALUES
