-- Table: weekly_report
DROP TABLE IF EXISTS `weekly_report`;
CREATE TABLE `weekly_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `therapist_id` int NOT NULL,
  `week_start` date NOT NULL,
  `week_end` date NOT NULL,
  `report_text` text,
  `avg_score` float DEFAULT NULL,
  `sessions_count` int DEFAULT NULL,
  `objectives_achieved` int DEFAULT NULL,
  `objectives_total` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `therapist_id` (`therapist_id`),
  KEY `fk_weekly_report_created_by_id_user` (`created_by_id`),
  KEY `idx_weekly_report_patient` (`patient_id`),
  CONSTRAINT `fk_weekly_report_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `weekly_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `weekly_report_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=587 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

