-- Table: yape_transaction
DROP TABLE IF EXISTS `yape_transaction`;
CREATE TABLE `yape_transaction` (
  `id` int NOT NULL AUTO_INCREMENT,
  `operation_number` varchar(100) NOT NULL,
  `transaction_date` datetime NOT NULL,
  `sender_name` varchar(255) DEFAULT NULL,
  `amount` float NOT NULL,
  `message` text,
  `category` varchar(50) DEFAULT NULL,
  `is_expense` tinyint(1) DEFAULT NULL,
  `expense_id` int DEFAULT NULL,
  `receipt_image_path` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `import_batch_id` varchar(100) DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_yape_transaction_operation_number` (`operation_number`),
  KEY `expense_id` (`expense_id`),
  KEY `fk_yape_transaction_created_by_id_user` (`created_by_id`),
  KEY `idx_yape_operation` (`operation_number`),
  KEY `idx_yape_category` (`category`),
  CONSTRAINT `fk_yape_transaction_created_by_id_user` FOREIGN KEY (`created_by_id`) REFERENCES `user` (`id`),
  CONSTRAINT `yape_transaction_ibfk_1` FOREIGN KEY (`expense_id`) REFERENCES `expense` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

SET FOREIGN_KEY_CHECKS = 1;
